from dataclasses import dataclass
from typing import Optional
from taf.hw.rf_diagnostic_card import rf_diagnostic_card
from taf.hw.rmod_serial_interface.clients.pyro.pyro_server.exceptions import LoginFailedError
from taf.rfrl.procedures.resources.python.logger import log_input_and_output, log_operation, \
    log_warning, log_result
from taf.rfrl.procedures.resources.python.testline.TestLine import TestLine
from time import sleep

import re


class RmodSerialConsoleOperations:

    def __init__(self):
        self._rmod_console = None
        self._logs_path = None
        self._active_rdc_aliases_map = {}

    @property
    def active_serial_console_connections_aliases_map(self):
        return self._active_rdc_aliases_map

    @property
    def rmod_serial_console(self):
        if self._rmod_console is None:
            self._rmod_console = rf_diagnostic_card()
        return self._rmod_console

    @log_input_and_output
    def get_init_serial_console_alias_for_serial_number(self, serial_number: str) -> Optional[str]:
        """Gets init alias for given serial number from active serial console connections.
        :param serial_number: Serial number of RMOD
        :type serial_number: str
        :return: Init alias of RMOD with given serial number or None if not found
        :rtype: str or None
        """
        for init_alias, connected_rmod in self.active_serial_console_connections_aliases_map.items():
            if connected_rmod.serial_number == serial_number:
                return init_alias
        return None

    @log_input_and_output
    def open_connections_and_initialize_log_collection_using_serial_console(
            self,
            logs_path: str,
            bts_type: str = "GNB",
            custom_rmod_setup_yaml_path: str = None,
            use_init_credentials: bool = False,
            **kwargs
    ):
        """Creates Serial Connection instance and connection aliases for each radio config informing about connection.
        :param logs_path: Path to directory where logs from radio will be stored
        :type logs_path: str
        :param bts_type: Type of BTS. Either "GNB" or "ENB". Defaults to "GNB"
        :type bts_type: str
        :param custom_rmod_setup_yaml_path: Path to custom RMOD serial connection setup yaml file.
                                           Defaults to None which means no custom setup is used.
        :type custom_rmod_setup_yaml_path: str
        :param use_init_credentials : Whether to use initial credentials for RMOD serial connection setup.
                                      Defaults to False.
        :type use_init_credentials : bool
        :param kwargs: Additional parameters to set up resources needed for Pyro server connection that are passed
                       to the `setup_host` method of the `rmod_serial_interface` library.
        :type kwargs: dict
        :return: None
        """
        self._logs_path = logs_path
        self.rmod_serial_console.prepare_log_directory_and_connection_setup(
            main_log_directory=logs_path,
            connection_setup=custom_rmod_setup_yaml_path)
        radio_configs = TestLine().get_radios_configs(bts_type=bts_type)
        for init_id, config in enumerate(radio_configs):
            init_id = str(init_id)
            try:
                rdc_aliases = self.rmod_serial_console.setup_connections(
                    config, init_id, log_to_console=False, use_init_credentials=use_init_credentials, **kwargs)
            except Exception as rsi_error:
                log_warning(f"Setup of rmod serial connection has failed with reason: {rsi_error}")
                continue
            if rdc_aliases:
                log_result(f"Created serial console connection for init id: {init_id} "
                           f"and serial: {config.serial_number}")
                self._active_rdc_aliases_map[init_id] = ConnectedRmod(init_id, rdc_aliases, config.serial_number)
            else:
                log_result(f"No serial connection to radio with init id: {init_id}")
        log_result(f"All available serial console connected RMODs with aliases map: "
                   f"{self.active_serial_console_connections_aliases_map}")

    @log_input_and_output
    def remove_rmods_with_lmi_connection_from_id_list(
            self,
            list_of_rmod_ids: list[int],
            ids_start_from_one: bool = False
    ) -> Optional[list[int]]:
        """
        Removes IDs of RMODs, which have active serial console (LMI/MUMIN) connection, from provided list.
        :param list_of_rmod_ids: List of RMOD IDs to check for active serial console (LMI/MUMIN) connection
        :type list_of_rmod_ids: list
        :param ids_start_from_one: True if RMOD IDs in provided list start from 1, False if RMOD IDs in provided
                                   list start from 0. Default False.
        :type ids_start_from_one: bool
        :return: List of RMOD IDs which do not have active serial console (LMI/MUMIN) connection
        :rtype: list or None
        """
        try:
            id_shift = 1 if ids_start_from_one else 0
            return [id_ for id_ in list_of_rmod_ids if
                    id_ - id_shift not in self.active_serial_console_connections_aliases_map.keys()]
        except AttributeError:
            log_result("Cannot remove RMODs with active serial connection because package was not initialized.")

    @log_input_and_output
    def send_command_to_rmod_using_serial_console(
            self,
            init_radio_id: str,
            cmd: str,
            uart_id: int = 0,
            as_rfsw: bool = True
    ):
        """
        Send command to given RMOD using serial console.
        :param init_radio_id: Alias of radio with serial diagnostic card which should be its init
                              configuration id (starts from 0)
        :type init_radio_id: str
        :param cmd: Command to be sent via serial console to RMOD.
        :type cmd: str
        :param uart_id: UART id. For RMODs with second UART it should be 1, defaults to 0 (first or only UART)
        :type uart_id: int
        :param as_rfsw: Send command as rfsw user, defaults to True
        :type as_rfsw: bool
        :return: None
        """
        uart_alias = self._get_alias_for_serial_console_connection(init_radio_id, uart_id)
        if uart_alias:
            log_operation(f'Following command will be sent via serial console with alias {uart_alias}:\n{cmd}')
            self.rmod_serial_console.send_command(alias=uart_alias, cmd=cmd, as_rfsw=as_rfsw)
        else:
            log_warning(f"Cannot sent command via serial console "
                        f"because alias for RMOD ID: {init_radio_id}, UART: {uart_id} does not exist!")

    @log_input_and_output
    def execute_command_on_rmod_using_serial_console(
            self,
            init_radio_id: str,
            cmd: str,
            timeout: int = 30,
            uart_id: int = 0,
            elevated: bool = False,
            write_output_to_logs: bool = True,
            as_rfsw: bool = True
    ) -> Optional[str]:
        """
        Executes command on given RMOD using serial console.
        :param init_radio_id: Alias of radio with serial diagnostic card which should be its init
                              configuration id (starts from 0)
        :type init_radio_id: str
        :param cmd: Command to be executed via serial console.
        :type cmd: str
        :param timeout: waiting time (in seconds) for command output, defaults to 30
        :type timeout: int
        :param uart_id: UART id. For RMODs with second UART it should be 1, defaults to 0 (first or only UART)
        :type uart_id: int
        :param elevated: try to run command with elevated permissions, defaults to False
        :type elevated: bool
        :param write_output_to_logs: By default command output is saved in the log file.
                                      It may be skipped when output is long, and it is not necessary to have them
                                      duplicated with RSI lib, defaults to True
        :type write_output_to_logs: bool
        :param as_rfsw: Execute command in RF Software shell context, defaults to True
        :type as_rfsw: bool
        :return: Command output from given RMOD or None if command could not be executed
        :rtype: str or None
        """
        uart_alias = self._get_alias_for_serial_console_connection(init_radio_id, uart_id)
        command_output = None
        if uart_alias:
            log_operation('Following command will be executed via serial'
                          f' console on RMOD with alias {uart_alias}:\n{cmd}')
            command_output = self.rmod_serial_console.execute_command(alias=uart_alias,
                                                                      cmd=cmd,
                                                                      wait_time=int(timeout),
                                                                      elevated=elevated,
                                                                      write_output_to_logs=write_output_to_logs,
                                                                      as_rfsw=as_rfsw)
        else:
            log_warning("Cannot execute command via Serial Console "
                        f"because alias for RMOD ID: {init_radio_id}, UART: {uart_id} does not exist!")
        return command_output

    @log_input_and_output
    def download_serial_console_log(
            self,
            init_radio_id: str,
            uart_id: int = 0,
            target_filepath: str = None
    ) -> Optional[str]:
        """
        Downloads serial console log for given RMOD.
        :param init_radio_id: Alias of radio with serial diagnostic card which should be its init
                              configuration id (starts from 0)
        :type init_radio_id: str
        :param uart_id: UART id. For RMODs with second UART it should be 1, defaults to 0 (first or only UART)
        :type uart_id: int
        :param target_filepath: Full path (including filename) where log file should be saved.
                                If None then default path will be used:
                                {logs_path}/rmod_{init_radio_id}_uart{uart_id}_serial_console.log
        :type target_filepath: str or None
        :return: Downloaded log file path or None if download was not possible
        :rtype: str or None
        """
        uart_alias = self._get_alias_for_serial_console_connection(init_radio_id, uart_id)
        if uart_alias:
            rmod_serial_number = self.active_serial_console_connections_aliases_map.get(init_radio_id).serial_number
            target_filepath = (target_filepath if target_filepath
                               else f"{self._logs_path}/rmod_{rmod_serial_number}_uart{uart_id}_serial_console.log")
            log_operation(f"Downloading serial console log for RMOD {rmod_serial_number} with alias {uart_alias}")
            self.rmod_serial_console.download_log(alias=uart_alias, target_filepath=target_filepath)
            return target_filepath
        else:
            log_warning("Cannot download serial console log "
                        f"because alias for RMOD ID: {init_radio_id}, UART: {uart_id} does not exist!")
        return None

    @log_input_and_output
    def switch_serial_to_node(self, init_radio_id: str, node: int, uart_id: int = 0):
        """
        Switch serial output to desired node in runtime on given RMOD. Currently supported generations are Chile
        and 7.1.
        :param init_radio_id: Alias of radio with serial diagnostic card which should be its init
                              configuration id (starts from 0)
        :type init_radio_id: str
        :param node: Node to switch. It should be called accordingly to the 'Logging capability - platforms overview'
                     documentation (http://nok.it/logging).
        :type node: int
        :param uart_id: UART id. For RMODs with second UART it should be 1, defaults to 0 (first or only UART)
                        To switch output of Thor interface use init RMOD id with uart_id=1
        :type uart_id: int
        :return: None
        """
        uart_alias = self._get_alias_for_serial_console_connection(init_radio_id, uart_id)
        log_operation(f"Switching serial console with alias '{uart_alias}' "
                      f"on RMOD:{init_radio_id} UART:{uart_id} to node {node}")
        self.rmod_serial_console.switch_serial_to_node(alias=uart_alias, node=node)

    @log_input_and_output
    def update_credentials_for_all_serial_console_connections(self, password: str, username: str = "serviceuser"):
        """
        Update username and password for all active serial console connections.
        :param password: New password to set
        :type password: str
        :param username: New username to set, defaults to "serviceuser"
        :type username: str
        :return: None
        """
        log_operation(f"Updating credentials for all serial console connections on aliases map: "
                      f"{self.active_serial_console_connections_aliases_map} "
                      f"with username: {username} and password: {password}")
        for init_id, rmod_connections in self.active_serial_console_connections_aliases_map.items():
            for rdc_alias in rmod_connections.rdc_lib_aliases:
                self.rmod_serial_console.set_rmod_credentials(alias=rdc_alias, password=password, username=username)

    @log_input_and_output
    def update_credentials_for_rmod_serial_console_connection(
            self,
            init_radio_id: str,
            password: str,
            username: str = "serviceuser"
    ):
        """
        Update username and password for a RMOD all serial console connections (all UARTs).
        :param init_radio_id: Alias of radio with serial diagnostic card which should be its init
                              configuration id (starts from 0)
        :type init_radio_id: str
        :param password: New password to set
        :type password: str
        :param username: New username to set, defaults to "serviceuser"
        :type username: str
        :return: None
        """
        uart_connections = self.active_serial_console_connections_aliases_map[init_radio_id]
        log_operation(f"Updating credentials for RMOD: {init_radio_id} serial console connection(s): {uart_connections}"
                      f" with username: {username} and password: {password}")
        for rdc_alias in uart_connections.rdc_lib_aliases:
            self.rmod_serial_console.set_rmod_credentials(alias=rdc_alias, password=password, username=username)

    @log_input_and_output
    def confirm_serial_console_connection_is_not_possible_in_edsm_state(
            self,
            logs_path: str,
            init_radio_id: str,
            ru_config: object,
            number_of_retries: int = 3,
            custom_rmod_setup_yaml_path: str = None
    ) -> bool:
        """
        Confirms that serial console connection to RMOD in EDSM state is not possible.
        Method calls setup connection without alias, so the RMOD serial number should be returned as an alias.
        :param logs_path: Path to directory where logs from radio will be stored
        :type logs_path: str
        :param init_radio_id: ID of radio with serial diagnostic card, which should match its init
                              configuration id (starts from 0)
        :type init_radio_id: str
        :param ru_config: RU configuration object
        :type ru_config: object
        :param number_of_retries: Number of attempts to check connection
        :type number_of_retries: int
        :param custom_rmod_setup_yaml_path: Path to custom RMOD setup YAML configuration
        :type custom_rmod_setup_yaml_path: str
        :return: True if connection is not possible, False otherwise
        :rtype: bool
        """
        aliases = []
        result = False
        success_msg = f"RU {init_radio_id} in EDSM State is NOT reachable via LMI board as expected."
        log_operation(f"Checking if RU {init_radio_id} in EDSM State is not reachable via LMI board...")

        for attempt in range(int(number_of_retries)):
            self.rmod_serial_console.prepare_log_directory_and_connection_setup(
                main_log_directory=logs_path, connection_setup=custom_rmod_setup_yaml_path)
            try:
                aliases = self.rmod_serial_console.setup_connections(ru_config=ru_config)
                logged_in = [self._is_logged_in(alias) for alias in aliases]
                if not all(logged_in):
                    log_result(success_msg)
                    result = True
                    return result
                log_warning(f"RU {init_radio_id} in EDSM State is connected with serial console aliases: {aliases} "
                            f"in attempt {attempt + 1}, which is NOT expected!")
                sleep(10)
            except LoginFailedError:
                log_result(success_msg)
                result = True
                return result
            finally:
                if result is False and aliases and attempt == int(number_of_retries) - 1:
                    self.rmod_serial_console.take_snapshot(alias=aliases[0], target_path_on_vm=logs_path)
                self.rmod_serial_console.disconnect_all_rmods()
        return False

    def close_serial_console_connections(self):
        """
        Close connection to all serial consoles and clear the active connections map.
        """
        try:
            log_operation(f"Disconnecting serial console connections on aliases map: "
                          f"{self.active_serial_console_connections_aliases_map}")
            for init_id, rmod_connections in self.active_serial_console_connections_aliases_map.items():
                for rdc_alias in rmod_connections.rdc_lib_aliases:
                    try:
                        self.rmod_serial_console.disconnect(rdc_alias)
                    except (KeyError, LoginFailedError, TimeoutError) as disconnect_error:
                        log_warning(f"Problem with disconnecting serial console with alias {rdc_alias} "
                                    f"for RMOD ID: {init_id} due to: {disconnect_error}")
            self._active_rdc_aliases_map = {}
        except AttributeError:
            log_result("Cannot close serial connections to RMODs because package was not initialized.")

    @log_input_and_output
    def _get_alias_for_serial_console_connection(self, init_radio_id: str, uart_id: int) -> Optional[str]:
        """
        Gets internal serial console alias to communicate
        :param init_radio_id: Alias of radio with serial diagnostic card which should be its init
                              configuration id (starts from 0)
        :type init_radio_id: str
        :param uart_id: UART id. 0 for first, 1 for second
        :type uart_id: int
        :return: Alias of serial console connection on given UART or None if not found
        :rtype: str or None
        """
        try:
            return self.active_serial_console_connections_aliases_map[init_radio_id].rdc_lib_aliases[uart_id]
        except KeyError:
            log_warning(f"Cannot get alias - init RMOD ID: {init_radio_id} "
                        f"and uart_id: {uart_id} does not exist!")

    @log_input_and_output
    def _is_logged_in(self, alias) -> bool:
        """
        Checks if the output indicates a successful login.
        :param alias: alias of the serial console connection
        :type alias: str
        :return: True if login is successful, False otherwise.
        :rtype: bool
        """
        output = self.rmod_serial_console.execute_command(
            alias=alias, cmd="date +%s", as_rfsw=False, wait_time=10)
        if not output or not output.strip():
            return False

        for line in output.strip().split('\n'):
            clean_line = line.strip()
            if re.match(r'^\d{5,}$', clean_line):
                return True

        return False


@dataclass
class ConnectedRmod:
    init_alias: str
    rdc_lib_aliases: list
    serial_number: str
